/**
 * The Allora I extractor: reads the game's data tables and renders the YAML
 * files and the report. Rendering is pure, so the same page always gives the
 * same bytes.
 */
import { stringify } from 'yaml';
import type { CollectedTable } from './collect';
import { KINDS } from './kinds';
import { renderReport, type KindCount, type ReportInput } from './report';
import { DropLog, attachSubs, buildEntries, tableRows, type Entry } from './transform';

export const SOURCE_FILE = 'canon/allora-1.html';
export const OUT_DIR = 'content/canon/allora1';

export const HEADER =
  '# Generated by `pnpm extract` from canon/allora-1.html. Do not edit by hand.\n' +
  '# Change it only by re-running the extractor, or in a PR labelled canon-change.\n';

export function toYaml(entries: Entry[]): string {
  return HEADER + stringify(entries, { lineWidth: 0, aliasDuplicateObjects: false });
}

/** Path (relative to OUT_DIR) → file contents. */
export type Output = Map<string, string>;

export function render(
  tables: Record<string, CollectedTable>,
  source: { sha256: string; tableNames: string[] },
): Output {
  const log = new DropLog();
  const out: Output = new Map();
  const counts: KindCount[] = [];
  const unreadable: ReportInput['unreadable'] = [];
  const idMismatches: ReportInput['idMismatches'] = [];
  const tableTotals: Record<string, number> = {};
  let orphanSubs: string[] = [];

  for (const [name, t] of Object.entries(tables)) {
    if (name !== '__page_errors__' && t.error) unreadable.push({ table: name, error: t.error });
  }

  for (const def of KINDS) {
    const t = tables[def.table];
    if (!t || t.error || t.value === undefined) continue;
    const rows = tableRows(t.value, def.table);
    tableTotals[def.table] = rows.length;
    const gameCount = def.filter
      ? rows.filter(([id, raw]) => def.filter!(id, raw)).length
      : rows.length;
    const { entries, idMismatches: mism } = buildEntries(def, t.value, log);
    if (mism.length > 0) idMismatches.push({ kind: def.kind, ids: mism });
    if (def.kind === 'place') {
      orphanSubs = attachSubs(entries, tables.SUBS?.value, tables.HIDDEN_SUBS?.value, log).orphans;
    }
    out.set(`${def.file}.yaml`, toYaml(entries));
    counts.push({
      file: def.file,
      kind: def.kind,
      table: def.table,
      about: def.about,
      gameCount,
      written: entries.length,
    });
  }

  const used = new Set([...KINDS.map((k) => k.table), 'SUBS', 'HIDDEN_SUBS']);
  const notExtracted = source.tableNames.filter((n) => !used.has(n)).sort();

  out.set(
    'REPORT.md',
    renderReport({
      sourceFile: SOURCE_FILE,
      sourceSha256: source.sha256,
      counts,
      tableTotals,
      dropped: log.list(),
      unreadable,
      idMismatches,
      orphanSubs,
      pageErrors: tables.__page_errors__?.error,
      notExtracted,
    }),
  );
  return out;
}

/** Names of the page's top-level constants, read from the source text. */
export function topLevelTableNames(html: string): string[] {
  const names = new Set<string>();
  for (const m of html.matchAll(/^(?:const|let|var) ([A-Z][A-Z0-9_]*)\s*=\s*[[{]/gm)) {
    if (m[1]) names.add(m[1]);
  }
  return [...names];
}
